public sealed record PaymentDto(
    Guid Id,
    string IdempotencyKey,
    string CustomerId,
    Guid FromAccountId,
    Guid ToAccountId,
    decimal Amount,
    string Currency,
    PaymentStatus Status,
    Guid? TransferId,
    string? Reference,
