using Bank.Data;
using Bank.Modules.Accounts.Application;
using Bank.Modules.Auth.Application;
using Bank.Modules.Fx.Application;
using Bank.Modules.Ledger.Application;
using Bank.Modules.Ledger.Domain;
using Bank.Modules.Payments.Domain;
using Bank.Shared.Events;
using Bank.Shared.Settings;
using Bank.Shared.Time;
using Microsoft.EntityFrameworkCore;

namespace Bank.Modules.Payments.Application;

public sealed record PaymentRequest(string IdempotencyKey, Guid FromAccountId, Guid ToAccountId, decimal Amount, string? Reference);

public interface IPaymentService
{
    Task<Payment> PayAsync(PaymentRequest request, CancellationToken ct = default);
    Task<IReadOnlyList<Payment>> ForCustomerAsync(string customerId, CancellationToken ct = default);
}

public sealed class PaymentService : IPaymentService
{
    private readonly BankDbContext _db;
    private readonly ILedger _ledger;
    private readonly IAccountService _accounts;
    private readonly ICurrentUser _user;
    private readonly IClock _clock;
    private readonly BankSettings _settings;
    private readonly IFxService _fx;
    private readonly IEventBus _bus;

    public PaymentService(
        BankDbContext db,
        ILedger ledger,
        IAccountService accounts,
        ICurrentUser user,
        IClock clock,
        BankSettings settings,
        IFxService fx,
        IEventBus bus)
    {
        _db = db;
        _ledger = ledger;
        _accounts = accounts;
        _user = user;
        _clock = clock;
        _settings = settings;
        _fx = fx;
        _bus = bus;
    }

    public async Task<Payment> PayAsync(PaymentRequest request, CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(request);
        if (string.IsNullOrWhiteSpace(request.IdempotencyKey))
            throw new ArgumentException("Idempotency key is required.", nameof(request));
        if (request.Amount <= 0)
            throw new ArgumentException("Amount must be greater than zero.", nameof(request));
        if (Math.Round(request.Amount, 2, MidpointRounding.AwayFromZero) != request.Amount)
            throw new ArgumentException("Amount must have at most two decimal places.", nameof(request));

        var customerId = _user.UserId;

        var fromAccount = await _accounts.GetAsync(request.FromAccountId, ct);
        if (fromAccount is null || !string.Equals(fromAccount.OwnerId, customerId, StringComparison.Ordinal))
            throw new UnauthorizedAccessException("Source account is not owned by the current user.");

        var existing = await _db.Payments.FirstOrDefaultAsync(
            p => p.CustomerId == customerId && p.IdempotencyKey == request.IdempotencyKey, ct);
        if (existing is not null)
            return existing;

        var isRelational = _db.Database.IsRelational();
        await using var tx = isRelational && _db.Database.CurrentTransaction is null
            ? await _db.Database.BeginTransactionAsync(ct)
            : null;

        var toAccount = await _accounts.GetAsync(request.ToAccountId, ct)
            ?? throw new KeyNotFoundException($"Account {request.ToAccountId} not found.");

        var now = _clock.UtcNow;
        var dayStart = new DateTimeOffset(now.UtcDateTime.Date, TimeSpan.Zero);
        var dayEnd = dayStart.AddDays(1);
        var dailyPayments = await _db.Payments
            .Where(p => p.CustomerId == customerId
                        && p.Status == PaymentStatus.Completed
                        && p.CreatedAt >= dayStart
                        && p.CreatedAt < dayEnd)
            .Select(p => new { p.Amount, p.Currency })
            .ToListAsync(ct);
        var dailyTotalEur = dailyPayments.Sum(p => _fx.Convert(p.Amount, p.Currency, "EUR"));
        var requestEur = _fx.Convert(request.Amount, fromAccount.Currency, "EUR");
        if (dailyTotalEur + requestEur > _settings.DailyTransferLimit)
            throw new DailyLimitExceededException();

        var sourceCurrency = fromAccount.Currency;
        var destinationCurrency = toAccount.Currency;
        var sameCurrency = string.Equals(sourceCurrency, destinationCurrency, StringComparison.OrdinalIgnoreCase);

        decimal rate;
        decimal creditedAmount;
        string creditedCurrency;
        Guid transferId;

        if (sameCurrency)
        {
            rate = 1m;
            creditedAmount = request.Amount;
            creditedCurrency = sourceCurrency;
            transferId = await _ledger.PostTransferAsync(
                request.FromAccountId,
                request.ToAccountId,
                request.Amount,
                request.Reference ?? "",
                ct);
        }
        else
        {
            rate = _fx.Rate(sourceCurrency, destinationCurrency);
            creditedAmount = _fx.Convert(request.Amount, sourceCurrency, destinationCurrency);
            if (creditedAmount <= 0)
                throw new ArgumentException("Converted amount must be greater than zero.", nameof(request));

            creditedCurrency = destinationCurrency;
            var sourceClearing = BankAccounts.For(BankAccountKind.FxClearing, sourceCurrency);
            var destinationClearing = BankAccounts.For(BankAccountKind.FxClearing, destinationCurrency);

            await _ledger.PostTransferAsync(
                request.FromAccountId,
                sourceClearing,
                request.Amount,
                request.Reference ?? "",
                ct);

            transferId = await _ledger.PostTransferAsync(
                destinationClearing,
                request.ToAccountId,
                creditedAmount,
                request.Reference ?? "",
                ct);
        }

        var payment = new Payment
        {
            IdempotencyKey = request.IdempotencyKey,
            CustomerId = customerId,
            FromAccountId = request.FromAccountId,
            ToAccountId = request.ToAccountId,
            Amount = request.Amount,
            Currency = sourceCurrency,
            CreditedAmount = creditedAmount,
            CreditedCurrency = creditedCurrency,
            Rate = rate,
            Reference = request.Reference,
            CreatedAt = now,
        };
        payment.Complete(transferId);

        _db.Payments.Add(payment);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            if (tx is not null)
                await tx.RollbackAsync(ct);
            _db.ChangeTracker.Clear();

            var stored = await _db.Payments.FirstOrDefaultAsync(
                p => p.CustomerId == customerId && p.IdempotencyKey == request.IdempotencyKey, ct);
            if (stored is not null)
                return stored;

            throw;
        }

        if (tx is not null)
            await tx.CommitAsync(ct);

        await _bus.PublishAsync(
            new PaymentCompleted(payment.Id, customerId, payment.Amount, payment.Currency, now),
            ct);

        return payment;
    }

    public async Task<IReadOnlyList<Payment>> ForCustomerAsync(string customerId, CancellationToken ct = default) =>
        await _db.Payments
            .Where(p => p.CustomerId == customerId)
            .OrderByDescending(p => p.CreatedAt)
            .ToListAsync(ct);
}


