        };

    public decimal Rate(string fromCurrency, string toCurrency)
    {
        var fromRate = GetUnitsPerEur(fromCurrency, nameof(fromCurrency));
        var toRate = GetUnitsPerEur(toCurrency, nameof(toCurrency));

        if (string.Equals(fromCurrency, toCurrency, StringComparison.OrdinalIgnoreCase))
            return 1m;

        if (string.Equals(fromCurrency, "EUR", StringComparison.OrdinalIgnoreCase))
            return toRate;

        if (string.Equals(toCurrency, "EUR", StringComparison.OrdinalIgnoreCase))
            return 1m / fromRate;

        return (1m / fromRate) * toRate;
    }

    public decimal Convert(decimal amount, string fromCurrency, string toCurrency)
    {
        var fromRate = GetUnitsPerEur(fromCurrency, nameof(fromCurrency));
        var toRate = GetUnitsPerEur(toCurrency, nameof(toCurrency));

        if (string.Equals(fromCurrency, toCurrency, StringComparison.OrdinalIgnoreCase))
            return Math.Round(amount, 2, MidpointRounding.AwayFromZero);

        var inEur = string.Equals(fromCurrency, "EUR", StringComparison.OrdinalIgnoreCase)
            ? amount
            : amount / fromRate;

        var converted = string.Equals(toCurrency, "EUR", StringComparison.OrdinalIgnoreCase)
            ? inEur
            : inEur * toRate;

        return Math.Round(converted, 2, MidpointRounding.AwayFromZero);
    }

    private static decimal GetUnitsPerEur(string currency, string paramName)
    {
        if (string.IsNullOrWhiteSpace(currency) || !UnitsPerEur.TryGetValue(currency, out var rate))
