        var minFee = _fx.Convert(MinFeeEur, "EUR", fromCurrency);
        var maxFee = _fx.Convert(MaxFeeEur, "EUR", fromCurrency);
        var clamped = Math.Clamp(rawFee, minFee, maxFee);
