using Bank.Modules.Customers.Domain;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace Bank.Modules.Customers.Api;

public sealed record CustomerDto(
    string Id,
    string FullName,
    string Email,
    string NationalId,
    DateOnly DateOfBirth,
    KycStatus Status,
    string? DecidedBy,
    DateTimeOffset RegisteredAt);

public sealed record CustomerSummaryDto(
    string Id,
    string FullName,
    string Email,
    KycStatus Status,
    string? DecidedBy,
    DateTimeOffset RegisteredAt);

[ApiController]
[Route("api/customers")]
[Authorize(Policy = Policies.Customer)]
public sealed class CustomersController : ControllerBase
{
    private readonly ICustomerService _customers;
    private readonly ICurrentUser _user;

    public CustomersController(ICustomerService customers, ICurrentUser user)
    {
        _customers = customers;
        _user = user;
    }

    [HttpPost]
    public async Task<ActionResult<CustomerDto>> Register(RegisterCustomerRequest request, CancellationToken ct)
    {
        var c = await _customers.RegisterAsync(request, ct);
        return ToDto(c);
    }

    [HttpGet("me")]
    public async Task<ActionResult<CustomerDto>> Me(CancellationToken ct)
    {
        var c = await _customers.GetAsync(_user.UserId, ct);
        if (c is null)
            return NotFound();
        return ToDto(c);
    }

    [HttpPost("{id}/verify")]
    [Authorize(Policy = Policies.Compliance)]
    public async Task<ActionResult<CustomerSummaryDto>> Verify(string id, CancellationToken ct)
    {
        var c = await _customers.VerifyAsync(id, ct);
        return ToSummaryDto(c);
    }

    [HttpPost("{id}/reject")]
    [Authorize(Policy = Policies.Compliance)]
    public async Task<ActionResult<CustomerSummaryDto>> Reject(string id, CancellationToken ct)
    {
        var c = await _customers.RejectAsync(id, ct);
        return ToSummaryDto(c);
    }

    private static CustomerDto ToDto(Customer c) =>
        new(c.Id, c.FullName, c.Email, c.NationalId, c.DateOfBirth, c.Status, c.DecidedBy, c.RegisteredAt);

    private static CustomerSummaryDto ToSummaryDto(Customer c) =>
        new(c.Id, c.FullName, c.Email, c.Status, c.DecidedBy, c.RegisteredAt);
}


