using Bank.Shared;

namespace Bank.Modules.Cards.Domain;

public enum CardStatus
{
    Active,
    Frozen,
    Cancelled,
}

public sealed class Card
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public Guid AccountId { get; set; }
    public string CustomerId { get; set; } = "";
    [Pii] public string Number { get; set; } = "";
    public string Last4 { get; set; } = "";
    public CardStatus Status { get; private set; } = CardStatus.Active;
    public decimal PerTransactionLimit { get; set; } = 2000m;

    public void Freeze()
    {
        if (Status != CardStatus.Active)
            throw new InvalidOperationException($"Cannot freeze card in status {Status}.");
        Status = CardStatus.Frozen;
    }

    public void Unfreeze()
    {
        if (Status != CardStatus.Frozen)
            throw new InvalidOperationException($"Cannot unfreeze card in status {Status}.");
        Status = CardStatus.Active;
    }

    public void Cancel()
    {
        if (Status == CardStatus.Cancelled)
            throw new InvalidOperationException("Cancelled card cannot be modified.");
        Status = CardStatus.Cancelled;
    }
}


