public sealed record PaymentDto(
    Guid Id,
    string IdempotencyKey,
    string CustomerId,
    Guid FromAccountId,
    Guid ToAccountId,
    decimal Amount,
    string Currency,
    PaymentStatus Status,
    Guid? TransferId,
    string? Reference,
    DateTimeOffset CreatedAt,
    decimal Fee = 0m);

[ApiController]
[Route("api/payments")]
[Authorize(Policy = Policies.Customer)]
public sealed class PaymentsController : ControllerBase
{
    private readonly IPaymentService _payments;
    private readonly ICurrentUser _user;

    public PaymentsController(IPaymentService payments, ICurrentUser user)
    {
        _payments = payments;
        _user = user;
    }

    [HttpGet("quote")]
    public async Task<ActionResult<PaymentQuote>> Quote(
        [FromQuery] Guid from,
        [FromQuery] Guid to,
        [FromQuery] decimal amount,
        CancellationToken ct)
    {
        try
        {
            var quote = await _payments.QuoteAsync(from, to, amount, ct);
            return Ok(quote);
        }
        catch (UnauthorizedAccessException ex)
        {
            return StatusCode(StatusCodes.Status403Forbidden, new { error = ex.Message });
        }
        catch (KeyNotFoundException ex)
        {
            return NotFound(new { error = ex.Message });
        }
        catch (ArgumentException ex)
        {
            return BadRequest(new { error = ex.Message });
        }
        catch (InvalidOperationException ex)
        {
            return BadRequest(new { error = ex.Message });
        }
    }

    [HttpPost]
    public async Task<ActionResult<PaymentDto>> Pay(PaymentRequest request, CancellationToken ct)
    {
        try
        {
            var payment = await _payments.PayAsync(request, ct);
            return ToDto(payment);
        }
        catch (UnauthorizedAccessException ex)
        {
            return StatusCode(StatusCodes.Status403Forbidden, new { error = ex.Message });
        }
        catch (KeyNotFoundException ex)
        {
            return NotFound(new { error = ex.Message });
        }
        catch (ArgumentException ex)
        {
            return BadRequest(new { error = ex.Message });
        }
        catch (DailyLimitExceededException ex)
        {
            return BadRequest(new { error = ex.Message });
        }
        catch (InsufficientFundsException ex)
        {
            return BadRequest(new { error = ex.Message });
        }
        catch (CurrencyMismatchException ex)
        {
            return BadRequest(new { error = ex.Message });
        }
        catch (InvalidOperationException ex)
        {
            return BadRequest(new { error = ex.Message });
        }
    }

    [HttpGet]
    public async Task<IEnumerable<PaymentDto>> Mine(CancellationToken ct) =>
        (await _payments.ForCustomerAsync(_user.UserId, ct)).Select(ToDto);

    private static PaymentDto ToDto(Payment p) =>
        new(p.Id, p.IdempotencyKey, p.CustomerId, p.FromAccountId, p.ToAccountId, p.Amount, p.Currency, p.Status, p.TransferId, p.Reference, p.CreatedAt, p.Fee);
}


