    public async Task<Card> IssueAsync(Guid accountId, CancellationToken ct = default)
    {
        var customerId = _user.UserId;
        if (!await _accounts.IsOwnerAsync(accountId, customerId, ct))
            throw new UnauthorizedAccessException("Account is not owned by the current user.");

        var number = Random.Shared.NextInt64(1_000_000_000_000_000, 10_000_000_000_000_000).ToString();
        var card = new Card
        {
            AccountId = accountId,
            CustomerId = customerId,
            Number = number,
            Last4 = number[^4..],
            PerTransactionLimit = 2000m,
        };

        _db.Cards.Add(card);
        await _db.SaveChangesAsync(ct);
        await _bus.PublishAsync(new CardIssued(card.Id, customerId, card.Last4, _clock.UtcNow), ct);
