    }

    public async Task<Card> FreezeAsync(Guid cardId, CancellationToken ct = default)
    {
        var card = await GetOwnedCardAsync(cardId, ct);
        card.Freeze();
        await _db.SaveChangesAsync(ct);
        return card;
    }

    public async Task<Card> UnfreezeAsync(Guid cardId, CancellationToken ct = default)
    {
        var card = await GetOwnedCardAsync(cardId, ct);
        card.Unfreeze();
        await _db.SaveChangesAsync(ct);
        return card;
    }

    public async Task<Card> CancelAsync(Guid cardId, CancellationToken ct = default)
    {
        var card = await GetOwnedCardAsync(cardId, ct);
        card.Cancel();
        await _db.SaveChangesAsync(ct);
        return card;
    }

    public async Task<CardAuthorisation> AuthoriseAsync(Guid cardId, decimal amount, string merchant, CancellationToken ct = default)
    {
        if (amount <= 0)
            throw new ArgumentOutOfRangeException(nameof(amount), "Amount must be greater than zero.");

        var roundedAmount = Math.Round(amount, 2, MidpointRounding.AwayFromZero);
        if (roundedAmount <= 0)
            throw new ArgumentOutOfRangeException(nameof(amount), "Amount must be greater than zero.");

        var card = await _db.Cards.FirstOrDefaultAsync(c => c.Id == cardId, ct)
                   ?? throw new KeyNotFoundException($"Card {cardId} not found.");

        if (card.Status != CardStatus.Active)
        {
            await _bus.PublishAsync(new CardPaymentDeclined(card.Id, "card not active", _clock.UtcNow), ct);
            return new CardAuthorisation(false, "card not active", null);
        }

        if (roundedAmount > card.PerTransactionLimit)
        {
            await _bus.PublishAsync(new CardPaymentDeclined(card.Id, "over limit", _clock.UtcNow), ct);
            return new CardAuthorisation(false, "over limit", null);
        }

        var merchantName = merchant ?? "";
        var transferId = Guid.Empty;
        var currency = "";
        var insufficientFunds = false;

        var isRelational = _db.Database.IsRelational();
        await using (var tx = isRelational && _db.Database.CurrentTransaction is null
            ? await _db.Database.BeginTransactionAsync(ct)
            : null)
        {
            var account = await _accounts.GetAsync(card.AccountId, ct)
                          ?? throw new KeyNotFoundException($"Account {card.AccountId} not found.");
            currency = account.Currency;

            if (!account.AllowOverdraft && account.Balance < roundedAmount)
            {
                insufficientFunds = true;
                if (tx is not null)
                    await tx.RollbackAsync(ct);
            }
            else
            {
                try
                {
                    var suspenseAccountId = BankAccounts.For(BankAccountKind.Suspense, currency);
                    var reference = string.IsNullOrWhiteSpace(merchantName) ? "Card payment" : merchantName;
                    transferId = await _ledger.PostTransferAsync(
                        card.AccountId,
                        suspenseAccountId,
                        roundedAmount,
                        reference,
                        ct);

                    if (tx is not null)
                        await tx.CommitAsync(ct);
                }
                catch (InsufficientFundsException)
                {
                    insufficientFunds = true;
                    if (tx is not null)
                        await tx.RollbackAsync(ct);
                }
            }
        }

        if (insufficientFunds)
        {
            await _bus.PublishAsync(new CardPaymentDeclined(card.Id, "insufficient funds", _clock.UtcNow), ct);
            return new CardAuthorisation(false, "insufficient funds", null);
        }

        await _bus.PublishAsync(
            new CardPaymentAuthorised(card.Id, roundedAmount, currency, merchantName, _clock.UtcNow),
            ct);

        return new CardAuthorisation(true, null, transferId);
    }

    private async Task<Card> GetOwnedCardAsync(Guid cardId, CancellationToken ct)
    {
        var card = await _db.Cards.FirstOrDefaultAsync(c => c.Id == cardId, ct)
                   ?? throw new KeyNotFoundException($"Card {cardId} not found.");
        if (!string.Equals(card.CustomerId, _user.UserId, StringComparison.Ordinal))
            throw new UnauthorizedAccessException("Card is not owned by the current user.");
        return card;
    }
