# Payments — constitution
**Purpose:** Money transfers between accounts, inside the bank and across currencies.
**Owner:** Payments · **Risk:** HIGH
**Rules:** A customer pays only from an account they own. Each payment carries an idempotency key: the same key never pays twice. The daily limit from BankSettings applies per customer per UTC day, in EUR equivalent. Money moves only through the Ledger.
**Forbidden:** Paying twice for one key; skipping the limit or the fraud hold; trusting an account id without an ownership check.


===== src/Bank.Api/Modules/Payments/Domain/Payment.cs =====
using Bank.Shared;

namespace Bank.Modules.Payments.Domain;

public enum PaymentStatus
{
    Completed,
    Held,
    Rejected,
}

public sealed class Payment
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public string IdempotencyKey { get; set; } = "";
    public string CustomerId { get; set; } = "";
    public Guid FromAccountId { get; set; }
    public Guid ToAccountId { get; set; }
    public decimal Amount { get; set; }
    public string Currency { get; set; } = "EUR";
    public decimal Fee { get; set; }
    public decimal CreditedAmount { get; set; }
    public string CreditedCurrency { get; set; } = "EUR";
    public decimal Rate { get; set; } = 1m;
    public PaymentStatus Status { get; private set; } = PaymentStatus.Completed;
    public Guid? TransferId { get; set; }
    [Pii] public string? Reference { get; set; }
    public DateTimeOffset CreatedAt { get; set; }

    public void Complete(Guid transferId)
    {
        if (Status == PaymentStatus.Rejected)
            throw new InvalidOperationException($"Cannot complete payment in status {Status}.");
        Status = PaymentStatus.Completed;
        TransferId = transferId;
    }

    public void Hold()
    {
        if (Status != PaymentStatus.Completed && Status != PaymentStatus.Held)
            throw new InvalidOperationException($"Cannot hold payment in status {Status}.");
        Status = PaymentStatus.Held;
    }

    public void Reject()
    {
        if (Status == PaymentStatus.Completed)
            throw new InvalidOperationException("Cannot reject a completed payment.");
        Status = PaymentStatus.Rejected;
    }
}


