        var b = TestKit.Account(db, "bob");

        await Assert.ThrowsAsync<InsufficientFundsException>(() => TestKit.Ledger(db).PostTransferAsync(a, b, 10.01m, "too much"));
        Assert.Equal(10m, TestKit.Balance(db, a));
    }

