using Microsoft.EntityFrameworkCore;

namespace Bank.Modules.Loans.Application;

public sealed record LoanApplication(Guid DisbursementAccountId, decimal Principal, int TermMonths);

public interface ILoanService
{
    Task<Loan> ApplyAsync(LoanApplication application, CancellationToken ct = default);
    Task<Loan> GetAsync(Guid loanId, CancellationToken ct = default);
}

public sealed class LoanService(BankDbContext db, ILedger ledger, IAccountService accounts, ICurrentUser user, IClock clock, IEventBus bus, INotifier notifier) : ILoanService
{
    private const decimal MinPrincipal = 1000m;
    private const decimal MaxPrincipal = 50000m;
    private const int MinTermMonths = 6;
    private const int MaxTermMonths = 120;
    private const decimal FixedAnnualRatePercent = 5.5m;

    private readonly BankDbContext _db = db ?? throw new ArgumentNullException(nameof(db));
    private readonly ILedger _ledger = ledger ?? throw new ArgumentNullException(nameof(ledger));
    private readonly IAccountService _accounts = accounts ?? throw new ArgumentNullException(nameof(accounts));
    private readonly ICurrentUser _user = user ?? throw new ArgumentNullException(nameof(user));
    private readonly IClock _clock = clock ?? throw new ArgumentNullException(nameof(clock));
    private readonly IEventBus _bus = bus ?? throw new ArgumentNullException(nameof(bus));
    private readonly INotifier _notifier = notifier ?? throw new ArgumentNullException(nameof(notifier));

    public async Task<Loan> ApplyAsync(LoanApplication application, CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(application);

        if (application.Principal < MinPrincipal || application.Principal > MaxPrincipal)
            throw new ArgumentException($"Principal must be between {MinPrincipal} and {MaxPrincipal}.", nameof(application));

        if (application.TermMonths < MinTermMonths || application.TermMonths > MaxTermMonths)
            throw new ArgumentException($"TermMonths must be between {MinTermMonths} and {MaxTermMonths}.", nameof(application));

        var customerId = _user.UserId;
        if (!await _accounts.IsOwnerAsync(application.DisbursementAccountId, customerId, ct))
            throw new UnauthorizedAccessException("Disbursement account is not owned by the current user.");

        var now = _clock.UtcNow;
        var loan = new Loan
        {
            CustomerId = customerId,
            DisbursementAccountId = application.DisbursementAccountId,
            Principal = application.Principal,
            TermMonths = application.TermMonths,
            AnnualRatePercent = FixedAnnualRatePercent,
            MonthlyPayment = ComputeMonthlyPayment(application.Principal, application.TermMonths),
            AppliedAt = now,
        };

        _db.Loans.Add(loan);
        await _db.SaveChangesAsync(ct);
        await _bus.PublishAsync(new LoanSubmitted(loan.Id, loan.CustomerId, loan.Principal, now), ct);

        return loan;
    }

    public async Task<Loan> GetAsync(Guid loanId, CancellationToken ct = default)
    {
        var loan = await _db.Loans.FirstOrDefaultAsync(l => l.Id == loanId, ct)
                   ?? throw new KeyNotFoundException($"Loan {loanId} not found.");

        var callerId = _user.UserId;
        if (!string.Equals(loan.CustomerId, callerId, StringComparison.Ordinal) && !_user.IsInRole(Roles.LoanOfficer))
            throw new UnauthorizedAccessException("You are not authorized to view this loan.");

        return loan;
    }

    private static decimal ComputeMonthlyPayment(decimal principal, int termMonths)
    {
        var monthlyRate = 0.055m / 12m;
        var baseFactor = 1m + monthlyRate;
        var compoundFactor = 1m;
        for (var i = 0; i < termMonths; i++)
            compoundFactor *= baseFactor;

        var discountFactor = 1m / compoundFactor;
        var payment = principal * monthlyRate / (1m - discountFactor);
        return Math.Round(payment, 2, MidpointRounding.AwayFromZero);
    }
}
