namespace Bank.Modules.Loans.Api;

public sealed record ApproveLoanRequest(string? Note = null);

public sealed record RejectLoanRequest(string? Reason = null);

public sealed record LoanDto(
    Guid Id,
    string CustomerId,
    Guid DisbursementAccountId,
    decimal Principal,
    int TermMonths,
    decimal AnnualRatePercent,
    decimal MonthlyPayment,
    LoanStatus Status,
    string? DecidedBy,
    string? DecisionNote,
    DateTimeOffset AppliedAt);

[ApiController]
[Route("api/loans")]
[Authorize(Policy = Policies.Customer)]
public sealed class LoansController : ControllerBase
{
    private readonly ILoanService _loans;

    public LoansController(ILoanService loans)
    {
        _loans = loans;
    }

    [HttpPost]
    public async Task<ActionResult<LoanDto>> Apply(LoanApplication request, CancellationToken ct)
    {
        try
        {
            var loan = await _loans.ApplyAsync(request, ct);
            return ToDto(loan);
        }
        catch (UnauthorizedAccessException ex)
        {
            return StatusCode(StatusCodes.Status403Forbidden, new { error = ex.Message });
        }
        catch (ArgumentException ex)
        {
            return BadRequest(new { error = ex.Message });
        }
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<LoanDto>> Get(Guid id, CancellationToken ct)
    {
        try
        {
            var loan = await _loans.GetAsync(id, ct);
            return ToDto(loan);
        }
        catch (UnauthorizedAccessException ex)
        {
            return StatusCode(StatusCodes.Status403Forbidden, new { error = ex.Message });
        }
        catch (KeyNotFoundException ex)
        {
            return NotFound(new { error = ex.Message });
        }
    }

    [HttpPost("{id:guid}/approve")]
    [Authorize(Policy = Policies.LoanOfficer)]
    public async Task<ActionResult<LoanDto>> Approve(
        Guid id,
        [FromBody(EmptyBodyBehavior = EmptyBodyBehavior.Allow)] ApproveLoanRequest? request,
        CancellationToken ct)
    {
        try
        {
            var loan = await _loans.ApproveAsync(id, request?.Note, ct);
            return ToDto(loan);
        }
        catch (UnauthorizedAccessException ex)
        {
            return StatusCode(StatusCodes.Status403Forbidden, new { error = ex.Message });
        }
        catch (KeyNotFoundException ex)
        {
            return NotFound(new { error = ex.Message });
        }
        catch (InsufficientFundsException ex)
        {
            return BadRequest(new { error = ex.Message });
        }
        catch (InvalidOperationException ex)
        {
            return Conflict(new { error = ex.Message });
        }
    }

    [HttpPost("{id:guid}/reject")]
    [Authorize(Policy = Policies.LoanOfficer)]
    public async Task<ActionResult<LoanDto>> Reject(
        Guid id,
        [FromBody(EmptyBodyBehavior = EmptyBodyBehavior.Allow)] RejectLoanRequest? request,
        CancellationToken ct)
    {
        try
        {
            var loan = await _loans.RejectAsync(id, request?.Reason ?? "", ct);
            return ToDto(loan);
        }
        catch (UnauthorizedAccessException ex)
        {
            return StatusCode(StatusCodes.Status403Forbidden, new { error = ex.Message });
        }
        catch (KeyNotFoundException ex)
        {
            return NotFound(new { error = ex.Message });
        }
        catch (ArgumentException ex)
        {
            return BadRequest(new { error = ex.Message });
        }
        catch (InvalidOperationException ex)
        {
            return Conflict(new { error = ex.Message });
        }
    }

    private static LoanDto ToDto(Loan l) =>
        new(
            l.Id,
            l.CustomerId,
            l.DisbursementAccountId,
            l.Principal,
            l.TermMonths,
            l.AnnualRatePercent,
            l.MonthlyPayment,
            l.Status,
            l.DecidedBy,
            l.DecisionNote,
            l.AppliedAt);
}


