        var monthStart = new DateTimeOffset(year, month, 1, 0, 0, 0, TimeSpan.Zero);
        var monthEnd = year == 9999 && month == 12
            ? DateTimeOffset.MaxValue
            : month == 12
                ? new DateTimeOffset(year + 1, 1, 1, 0, 0, 0, TimeSpan.Zero)
                : new DateTimeOffset(year, month + 1, 1, 0, 0, 0, TimeSpan.Zero);

        var priorEntries = await _ledger.EntriesAsync(accountId, DateTimeOffset.MinValue, monthStart, ct);
        var openingBalance = Math.Round(
            priorEntries.Aggregate(0.00m, (sum, entry) => sum + entry.Amount),
            2,
            MidpointRounding.AwayFromZero);

        var monthEntries = await _ledger.EntriesAsync(accountId, monthStart, monthEnd, ct);
        var orderedEntries = monthEntries
            .OrderBy(e => e.CreatedAt)
            .ThenBy(e => e.Id)
            .ToList();

        var lines = new List<StatementLine>(orderedEntries.Count);
        var cumulativeAmount = 0.00m;
        foreach (var entry in orderedEntries)
        {
            cumulativeAmount += entry.Amount;
            var balanceAfter = Math.Round(openingBalance + cumulativeAmount, 2, MidpointRounding.AwayFromZero);
            lines.Add(new StatementLine(entry.CreatedAt, entry.Amount, balanceAfter, entry.Reference));
        }

        var closingBalance = lines.Count == 0 ? openingBalance : lines[^1].BalanceAfter;

        return new Statement(
            account.Id,
            year,
            month,
            account.Currency,
            openingBalance,
            closingBalance,
            lines);
    }
}


