using System.ComponentModel.DataAnnotations;

namespace Bank.Modules.Loans.Domain;

public enum LoanStatus
{
    Submitted,
    Rejected,
    Disbursed,
}

public sealed class Loan
{
    public Loan()
    {
    }

    public Guid Id { get; set; } = Guid.NewGuid();
    public string CustomerId { get; set; } = "";
    public Guid DisbursementAccountId { get; set; }
    public decimal Principal { get; set; }
    public int TermMonths { get; set; }
    public decimal AnnualRatePercent { get; set; }
    public decimal MonthlyPayment { get; set; }
    [ConcurrencyCheck] public LoanStatus Status { get; private set; } = LoanStatus.Submitted;
    public string? DecidedBy { get; set; }
    public string? DecisionNote { get; set; }
    public DateTimeOffset AppliedAt { get; set; }

    public void Disburse(string officerId, string? note = null)
    {
        if (Status != LoanStatus.Submitted)
            throw new InvalidOperationException($"Cannot disburse loan in status {Status}.");
        if (string.IsNullOrWhiteSpace(officerId))
            throw new ArgumentException("Officer id is required.", nameof(officerId));

        Status = LoanStatus.Disbursed;
        DecidedBy = officerId;
        DecisionNote = note;
    }

    public void Reject(string officerId, string reason)
    {
        if (Status != LoanStatus.Submitted)
            throw new InvalidOperationException($"Cannot reject loan in status {Status}.");
        if (string.IsNullOrWhiteSpace(officerId))
            throw new ArgumentException("Officer id is required.", nameof(officerId));
        if (string.IsNullOrWhiteSpace(reason))
            throw new ArgumentException("Rejection reason is required.", nameof(reason));

        Status = LoanStatus.Rejected;
        DecidedBy = officerId;
        DecisionNote = reason;
    }
}


