    {
        _cards = cards;
    }

    [HttpPost]
    public async Task<ActionResult<CardDto>> Issue(IssueCardRequest request, CancellationToken ct)
    {
        try
        {
            var card = await _cards.IssueAsync(request.AccountId, ct);
            return ToDto(card);
