}

public sealed class StatementService(ILedger ledger, IAccountService accounts, ICurrentUser user) : IStatementService
{
    private readonly ILedger _ledger = ledger ?? throw new ArgumentNullException(nameof(ledger));
    private readonly IAccountService _accounts = accounts ?? throw new ArgumentNullException(nameof(accounts));
    private readonly ICurrentUser _user = user ?? throw new ArgumentNullException(nameof(user));

    public async Task<Statement> ForMonthAsync(Guid accountId, int year, int month, CancellationToken ct = default)
    {
        if (year < 1 || year > 9999)
            throw new ArgumentOutOfRangeException(nameof(year), year, "Year must be between 1 and 9999.");
        if (month < 1 || month > 12)
            throw new ArgumentOutOfRangeException(nameof(month), month, "Month must be between 1 and 12.");

        var account = await _accounts.GetAsync(accountId, ct)
                      ?? throw new KeyNotFoundException($"Account {accountId} not found.");

        var isStaff =
            _user.IsInRole(Roles.Teller) ||
            _user.IsInRole(Roles.LoanOfficer) ||
            _user.IsInRole(Roles.ComplianceOfficer) ||
            _user.IsInRole(Roles.Admin);

        if (!isStaff && !await _accounts.IsOwnerAsync(accountId, _user.UserId, ct))
            throw new UnauthorizedAccessException("You are not authorized to view statements for this account.");

        var monthStart = new DateTimeOffset(year, month, 1, 0, 0, 0, TimeSpan.Zero);
        var monthEnd = new DateTimeOffset(year, month, DateTime.DaysInMonth(year, month), 0, 0, 0, TimeSpan.Zero);

        var priorEntries = await _ledger.EntriesAsync(accountId, DateTimeOffset.MinValue, monthStart, ct);
        var openingBalance = Math.Round(
            priorEntries.Aggregate(0.00m, (sum, entry) => sum + entry.Amount),
            2,
            MidpointRounding.AwayFromZero);

        var monthEntries = await _ledger.EntriesAsync(accountId, monthStart, monthEnd, ct);
        var orderedEntries = monthEntries
            .OrderBy(e => e.CreatedAt)
            .ThenBy(e => e.Id)
            .ToList();

        var lines = new List<StatementLine>(orderedEntries.Count);
        var cumulativeAmount = 0.00m;
        foreach (var entry in orderedEntries)
        {
            cumulativeAmount += entry.Amount;
            var balanceAfter = Math.Round(openingBalance + cumulativeAmount, 2, MidpointRounding.AwayFromZero);
            lines.Add(new StatementLine(entry.CreatedAt, entry.Amount, balanceAfter, entry.Reference));
        }

        var closingBalance = lines.Count == 0 ? openingBalance : lines[^1].BalanceAfter;

        return new Statement(
            account.Id,
            year,
            month,
            account.Currency,
            openingBalance,
            closingBalance,
            lines);
    }
}


