using Bank.Data;
using Bank.Modules.Accounts.Application;
using Bank.Modules.Auth.Application;
using Bank.Modules.Deposits.Domain;
using Bank.Modules.Ledger.Application;
using Bank.Modules.Ledger.Domain;
using Bank.Shared.Events;
using Bank.Shared.Money;
using Bank.Shared.Time;
using Microsoft.EntityFrameworkCore;

namespace Bank.Modules.Deposits.Application;

public interface IDepositService
{
    Task<TermDeposit> OpenAsync(Guid accountId, decimal principal, int termMonths, CancellationToken ct = default);
    Task<TermDeposit> MatureAsync(Guid depositId, CancellationToken ct = default);
    Task<TermDeposit> BreakAsync(Guid depositId, CancellationToken ct = default);
}

public sealed class DepositService(
    BankDbContext db,
    ILedger ledger,
    IAccountService accounts,
    ICurrentUser user,
    IClock clock,
    IEventBus bus) : IDepositService
{
    private readonly BankDbContext _db = db ?? throw new ArgumentNullException(nameof(db));
    private readonly ILedger _ledger = ledger ?? throw new ArgumentNullException(nameof(ledger));
    private readonly IAccountService _accounts = accounts ?? throw new ArgumentNullException(nameof(accounts));
    private readonly ICurrentUser _user = user ?? throw new ArgumentNullException(nameof(user));
    private readonly IClock _clock = clock ?? throw new ArgumentNullException(nameof(clock));
    private readonly IEventBus _bus = bus ?? throw new ArgumentNullException(nameof(bus));

    public async Task<TermDeposit> OpenAsync(Guid accountId, decimal principal, int termMonths, CancellationToken ct = default)
    {
        if (principal < 500m)
            throw new ArgumentException("Principal must be at least 500.", nameof(principal));
        if (MoneyMath.ToCents(principal) != principal)
            throw new ArgumentException("Principal must be whole cents.", nameof(principal));

        var annualRatePercent = termMonths switch
        {
            3 => 2.0m,
            6 => 2.5m,
            12 => 3.0m,
            _ => throw new ArgumentException($"Unsupported term {termMonths}. Supported terms are 3, 6, or 12 months.", nameof(termMonths)),
        };

        var customerId = _user.UserId;
        if (!await _accounts.IsOwnerAsync(accountId, customerId, ct))
            throw new UnauthorizedAccessException("Account is not owned by the current user.");

        var account = await _accounts.GetAsync(accountId, ct)
                      ?? throw new KeyNotFoundException($"Account {accountId} not found.");

        var now = _clock.UtcNow;
        var deposit = new TermDeposit
        {
            CustomerId = customerId,
            AccountId = accountId,
            Principal = principal,
            Currency = account.Currency,
            TermMonths = termMonths,
            AnnualRatePercent = annualRatePercent,
            OpenedAt = now,
            MaturesAt = now.AddMonths(termMonths),
            InterestPaid = 0m,
        };

        var isRelational = _db.Database.IsRelational();
        await using var tx = isRelational && _db.Database.CurrentTransaction is null
            ? await _db.Database.BeginTransactionAsync(ct)
            : null;

        var holdingAccountId = BankAccounts.For(BankAccountKind.DepositHolding, account.Currency);
        await _ledger.PostTransferAsync(
            accountId,
            holdingAccountId,
            principal,
            $"Deposit {deposit.Id} open",
            ct);

        _db.TermDeposits.Add(deposit);
        await _db.SaveChangesAsync(ct);

        if (tx is not null)
            await tx.CommitAsync(ct);

        await _bus.PublishAsync(
            new DepositOpened(deposit.Id, customerId, deposit.Principal, deposit.TermMonths, now),
            ct);

        return deposit;
    }

    public async Task<TermDeposit> MatureAsync(Guid depositId, CancellationToken ct = default)
    {
        var deposit = await _db.TermDeposits.FirstOrDefaultAsync(d => d.Id == depositId, ct)
                      ?? throw new KeyNotFoundException($"Deposit {depositId} not found.");

        if (deposit.Status != DepositStatus.Open)
            throw new InvalidOperationException($"Deposit {depositId} is not open.");

        var now = _clock.UtcNow;
        if (now < deposit.MaturesAt)
            throw new InvalidOperationException($"Deposit {depositId} has not reached maturity yet.");

        var interest = MoneyMath.ToCents(
            deposit.Principal * (deposit.AnnualRatePercent / 100m) * deposit.TermMonths / 12m);

        var isRelational = _db.Database.IsRelational();
        await using var tx = isRelational && _db.Database.CurrentTransaction is null
            ? await _db.Database.BeginTransactionAsync(ct)
            : null;

        var holdingAccountId = BankAccounts.For(BankAccountKind.DepositHolding, deposit.Currency);
        await _ledger.PostTransferAsync(
            holdingAccountId,
            deposit.AccountId,
            deposit.Principal,
            $"Deposit {deposit.Id} principal",
            ct);

        if (interest > 0m)
        {
            var interestExpenseAccountId = BankAccounts.For(BankAccountKind.InterestExpense, deposit.Currency);
            await _ledger.PostTransferAsync(
                interestExpenseAccountId,
                deposit.AccountId,
                interest,
                $"Deposit {deposit.Id} interest",
                ct);
        }

        deposit.Mature(interest);

        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException ex)
        {
            if (tx is not null)
                await tx.RollbackAsync(ct);
            throw new InvalidOperationException($"Deposit {depositId} is no longer open.", ex);
        }

        if (tx is not null)
            await tx.CommitAsync(ct);

        await _bus.PublishAsync(
            new DepositClosed(deposit.Id, deposit.CustomerId, deposit.InterestPaid, false, now),
            ct);

        return deposit;
    }

    public async Task<TermDeposit> BreakAsync(Guid depositId, CancellationToken ct = default)
    {
        var customerId = _user.UserId;
        var deposit = await _db.TermDeposits.FirstOrDefaultAsync(d => d.Id == depositId, ct)
                      ?? throw new KeyNotFoundException($"Deposit {depositId} not found.");

        if (!string.Equals(deposit.CustomerId, customerId, StringComparison.Ordinal))
            throw new UnauthorizedAccessException("Deposit is not owned by the current user.");

        if (deposit.Status != DepositStatus.Open)
            throw new InvalidOperationException($"Deposit {depositId} is not open.");

        var now = _clock.UtcNow;
        var isRelational = _db.Database.IsRelational();
        await using var tx = isRelational && _db.Database.CurrentTransaction is null
            ? await _db.Database.BeginTransactionAsync(ct)
            : null;

        var holdingAccountId = BankAccounts.For(BankAccountKind.DepositHolding, deposit.Currency);
        await _ledger.PostTransferAsync(
            holdingAccountId,
            deposit.AccountId,
            deposit.Principal,
            $"Deposit {deposit.Id} break",
            ct);

        deposit.BreakEarly();

        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException ex)
        {
            if (tx is not null)
                await tx.RollbackAsync(ct);
            throw new InvalidOperationException($"Deposit {depositId} is no longer open.", ex);
        }

        if (tx is not null)
            await tx.CommitAsync(ct);

        await _bus.PublishAsync(
            new DepositClosed(deposit.Id, deposit.CustomerId, 0m, true, now),
            ct);

        return deposit;
    }
}


