using Bank.Modules.Fx.Application;
using Bank.Shared.Money;

namespace Bank.Modules.Fees.Application;

public sealed record Fee(decimal Amount, string Currency);

public interface IFeeCalculator
{
    Fee Quote(decimal amount, string fromCurrency, string toCurrency);
}

public sealed class FeeCalculator(IFxService fx) : IFeeCalculator
{
    private const decimal FeeRate = 0.002m;
    private const decimal MinFeeEur = 0.50m;

    private readonly IFxService _fx = fx ?? throw new ArgumentNullException(nameof(fx));

    public Fee Quote(decimal amount, string fromCurrency, string toCurrency)
    {
        if (amount <= 0)
            throw new ArgumentOutOfRangeException(nameof(amount), "Amount must be greater than zero.");
        if (string.IsNullOrWhiteSpace(fromCurrency))
            throw new ArgumentException("Source currency is required.", nameof(fromCurrency));
        if (string.IsNullOrWhiteSpace(toCurrency))
            throw new ArgumentException("Destination currency is required.", nameof(toCurrency));

        if (string.Equals(fromCurrency, toCurrency, StringComparison.OrdinalIgnoreCase))
            return new Fee(0.00m, fromCurrency);

        var rawFee = FeeRate * amount;
        var minFee = _fx.Convert(MinFeeEur, "EUR", fromCurrency);
        var effectiveFee = Math.Max(rawFee, minFee);
        var rounded = MoneyMath.ToCents(effectiveFee);

        return new Fee(rounded, fromCurrency);
    }
}


