    private static async Task<IDisposable> AcquireKeyLockAsync(string customerId, string idempotencyKey, CancellationToken ct)
    {
        var key = (customerId, idempotencyKey);
        LockEntry entry;
        lock (KeyLocks)
        {
            if (!KeyLocks.TryGetValue(key, out entry!))
            {
                entry = new LockEntry();
                KeyLocks[key] = entry;
            }
            entry.RefCount++;
        }

        try
        {
            await entry.Semaphore.WaitAsync(ct);
            return new KeyLockReleaser(key, entry);
        }
        catch
        {
            ReleaseKeyLock(key, entry, acquired: false);
            throw;
        }
    }

    private static void ReleaseKeyLock((string CustomerId, string IdempotencyKey) key, LockEntry entry, bool acquired)
    {
        if (acquired)
            entry.Semaphore.Release();

        lock (KeyLocks)
        {
            entry.RefCount--;
            if (entry.RefCount == 0 && KeyLocks.TryGetValue(key, out var current) && ReferenceEquals(current, entry))
            {
                KeyLocks.TryRemove(key, out _);
                entry.Semaphore.Dispose();
            }
        }
    }

    private sealed class LockEntry
    {
        public SemaphoreSlim Semaphore { get; } = new(1, 1);
        public int RefCount;
    }

    private sealed class KeyLockReleaser : IDisposable
    {
        private readonly (string CustomerId, string IdempotencyKey) _key;
        private readonly LockEntry _entry;
        private int _disposed;

        public KeyLockReleaser((string CustomerId, string IdempotencyKey) key, LockEntry entry)
        {
            _key = key;
            _entry = entry;
        }

        public void Dispose()
        {
            if (Interlocked.Exchange(ref _disposed, 1) == 0)
                ReleaseKeyLock(_key, _entry, acquired: true);
        }
    }
}
