    public async Task<Payment> ReleaseAsync(Guid paymentId, CancellationToken ct = default)
    {
        if (!_user.IsInRole(Roles.ComplianceOfficer))
            throw new UnauthorizedAccessException("Only a compliance officer may release a held payment.");

        var officerId = _user.UserId;
        var payment = await _db.Payments.FirstOrDefaultAsync(p => p.Id == paymentId, ct)
                      ?? throw new KeyNotFoundException($"Payment {paymentId} not found.");

        if (string.Equals(payment.CustomerId, officerId, StringComparison.Ordinal))
            throw new UnauthorizedAccessException("A compliance officer cannot release their own payment.");

        if (payment.Status != PaymentStatus.Held)
            throw new InvalidOperationException($"Payment {paymentId} is not in Held status.");

        var suspenseAccountId = BankAccounts.For(BankAccountKind.Suspense, payment.Currency);
        var principalAmount = Math.Round(payment.Amount, 2, MidpointRounding.AwayFromZero);
        var feeAmount = Math.Round(payment.Fee, 2, MidpointRounding.AwayFromZero);

        var toAccount = await _db.Accounts.AsNoTracking()
            .FirstOrDefaultAsync(a => a.Id == payment.ToAccountId, ct);
        var isCrossCurrency = toAccount is not null
            && !string.Equals(payment.Currency, toAccount.Currency, StringComparison.OrdinalIgnoreCase);

        var isRelational = _db.Database.IsRelational();
        await using var tx = isRelational && _db.Database.CurrentTransaction is null
            ? await _db.Database.BeginTransactionAsync(ct)
            : null;

        try
        {
            Guid transferId;
            if (!isCrossCurrency)
            {
                transferId = await _ledger.PostTransferAsync(
                    suspenseAccountId,
                    payment.ToAccountId,
                    principalAmount,
                    $"Payment {payment.Id} release",
                    ct);
            }
            else
            {
                var creditedAmount = Math.Round(payment.CreditedAmount, 2, MidpointRounding.AwayFromZero);
                var sourceClearing = BankAccounts.For(BankAccountKind.FxClearing, payment.Currency);
                var destinationClearing = BankAccounts.For(BankAccountKind.FxClearing, toAccount!.Currency);

                await _ledger.PostTransferAsync(
                    suspenseAccountId,
                    sourceClearing,
                    principalAmount,
                    $"Payment {payment.Id} release",
                    ct);

                transferId = await _ledger.PostTransferAsync(
                    destinationClearing,
                    payment.ToAccountId,
                    creditedAmount,
                    $"Payment {payment.Id} release",
                    ct);
            }

            if (feeAmount > 0m)
            {
                await _ledger.PostTransferAsync(
                    suspenseAccountId,
                    BankAccounts.For(BankAccountKind.FeeIncome, payment.Currency),
                    feeAmount,
                    "Fee",
                    ct);
            }

            payment.Complete(transferId);

            try
            {
                await _db.SaveChangesAsync(ct);
            }
            catch (DbUpdateConcurrencyException ex)
            {
                if (tx is not null)
                    await tx.RollbackAsync(CancellationToken.None);
                _db.ChangeTracker.Clear();
                throw new InvalidOperationException($"Payment {paymentId} is no longer in Held status.", ex);
            }

            if (tx is not null)
                await tx.CommitAsync(ct);
        }
        catch
        {
            if (tx is not null && _db.Database.CurrentTransaction is not null)
                await tx.RollbackAsync(CancellationToken.None);
            _db.ChangeTracker.Clear();
            throw;
        }

        var now = _clock.UtcNow;
        await _notifier.NotifyAsync(
            payment.CustomerId,
            $"Payment {payment.Id} has been released.",
            ct);
        await _bus.PublishAsync(new PaymentReleased(payment.Id, officerId, now), ct);

        return payment;
    }

