        var officerId = _user.UserId;
        if (string.IsNullOrWhiteSpace(reason))
            throw new ArgumentException("Rejection reason is required.", nameof(reason));

        var payment = await _db.Payments.FirstOrDefaultAsync(p => p.Id == paymentId, ct)
                      ?? throw new KeyNotFoundException($"Payment {paymentId} not found.");

        if (string.Equals(payment.CustomerId, officerId, StringComparison.Ordinal))
            throw new UnauthorizedAccessException("A compliance officer cannot reject their own payment.");

        if (payment.Status != PaymentStatus.Held)
            throw new InvalidOperationException($"Payment {paymentId} is not in Held status.");

        var suspenseAccountId = BankAccounts.For(BankAccountKind.Suspense, payment.Currency);
        var refundAmount = Math.Round(payment.Amount + payment.Fee, 2, MidpointRounding.AwayFromZero);

        var isRelational = _db.Database.IsRelational();
        await using var tx = isRelational && _db.Database.CurrentTransaction is null
            ? await _db.Database.BeginTransactionAsync(ct)
            : null;

        try
        {
            await _ledger.PostTransferAsync(
                suspenseAccountId,
                payment.FromAccountId,
                refundAmount,
                $"Payment {payment.Id} rejected",
                ct);

            payment.Reject();

            try
            {
                await _db.SaveChangesAsync(ct);
            }
            catch (DbUpdateConcurrencyException ex)
            {
                if (tx is not null)
                    await tx.RollbackAsync(CancellationToken.None);
                _db.ChangeTracker.Clear();
                throw new InvalidOperationException($"Payment {paymentId} is no longer in Held status.", ex);
            }

            if (tx is not null)
                await tx.CommitAsync(ct);
        }
        catch
        {
            if (tx is not null && _db.Database.CurrentTransaction is not null)
                await tx.RollbackAsync(CancellationToken.None);
            _db.ChangeTracker.Clear();
            throw;
        }

        var now = _clock.UtcNow;
        await _notifier.NotifyAsync(
            payment.CustomerId,
            $"Payment {payment.Id} has been rejected and funds have been returned.",
            ct);
        await _bus.PublishAsync(new PaymentRejected(payment.Id, officerId, now), ct);

        return payment;
    }
}


