        INotifier? notifier = null,
        IEventBus? bus = null)
    {
        _db = db;
        _ledger = ledger;
        _accounts = accounts;
        _user = user;
        _clock = clock;
        _settings = settings;
        _fx = fx;
        _fees = fees;
        _notifier = notifier;
        _bus = bus;
    }

    public PaymentService(
        BankDbContext db,
        ILedger ledger,
        IAccountService accounts,
        ICurrentUser user,
        IClock clock,
        BankSettings settings,
        IFxService fx,
        IFeeCalculator fees,
        IEventBus bus)
        : this(db, ledger, accounts, user, clock, settings, fx, fees, null, bus)
    {
