    public PaymentService(
        BankDbContext db,
        ILedger ledger,
        IAccountService accounts,
        ICurrentUser user,
        IClock clock,
        BankSettings settings,
        IFxService fx,
        IEventBus bus)
        : this(db, ledger, accounts, user, clock, settings, fx, new FeeCalculator(fx), null, bus)
