- [M:Bank.Modules.Customers.Application.CustomerService.RegisterAsync(Bank.Modules.Customers.Application.RegisterCustomerRequest,System.Threading.CancellationToken)] method (new)
  AFTER:
    public async Task<Customer> RegisterAsync(RegisterCustomerRequest request, CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(request);
        if (string.IsNullOrWhiteSpace(request.FullName))
            throw new ArgumentException("Full name is required.", nameof(request));
        if (string.IsNullOrWhiteSpace(request.Email))
            throw new ArgumentException("Email is required.", nameof(request));
        if (string.IsNullOrWhiteSpace(request.NationalId))
            throw new ArgumentException("National id is required.", nameof(request));
        if (request.DateOfBirth == default)
            throw new ArgumentException("Date of birth is required.", nameof(request));

        var today = DateOnly.FromDateTime(_clock.UtcNow.UtcDateTime);
        if (request.DateOfBirth > today.AddYears(-18))
            throw new ArgumentException("Customer must be at least 18 years old.", nameof(request));

        var userId = _user.UserId;
        if (await _db.Customers.AnyAsync(c => c.Id == userId, ct))
            throw new InvalidOperationException("Customer is already registered.");

        var now = _clock.UtcNow;
        var customer = new Customer
        {
            Id = userId,
            FullName = request.FullName,
            Email = request.Email,
            NationalId = request.NationalId,
            DateOfBirth = request.DateOfBirth,
            RegisteredAt = now,
        };
        _db.Customers.Add(customer);
        await _db.SaveChangesAsync(ct);
        await _bus.PublishAsync(new CustomerRegistered(customer.Id, now), ct);
        return customer;
    }
- [M:Bank.Modules.Customers.Application.CustomerService.VerifyAsync(System.String,System.Threading.CancellationToken)] method (new)
  AFTER:
    public async Task<Customer> VerifyAsync(string customerId, CancellationToken ct = default)
    {
        if (!_user.IsInRole(Roles.ComplianceOfficer))
            throw new UnauthorizedAccessException("Only a compliance officer may verify a customer.");
        var officerId = _user.UserId;
        if (string.Equals(officerId, customerId, StringComparison.Ordinal))
            throw new UnauthorizedAccessException("A compliance officer cannot verify themselves.");

        var customer = await _db.Customers.FirstOrDefaultAsync(c => c.Id == customerId, ct)
                       ?? throw new KeyNotFoundException($"Customer {customerId} not found.");
        customer.Verify(officerId);
        await _db.SaveChangesAsync(ct);
        await _bus.PublishAsync(new CustomerVerified(customer.Id, officerId, customer.NationalId, _clock.UtcNow), ct);
        return customer;
    }
- [M:Bank.Modules.Customers.Application.CustomerService.RejectAsync(System.String,System.Threading.CancellationToken)] method (new)
  AFTER:
    public async Task<Customer> RejectAsync(string customerId, CancellationToken ct = default)
    {
        if (!_user.IsInRole(Roles.ComplianceOfficer))
            throw new UnauthorizedAccessException("Only a compliance officer may reject a customer.");
        var officerId = _user.UserId;
        if (string.Equals(officerId, customerId, StringComparison.Ordinal))
            throw new UnauthorizedAccessException("A compliance officer cannot reject themselves.");

        var customer = await _db.Customers.FirstOrDefaultAsync(c => c.Id == customerId, ct)
                       ?? throw new KeyNotFoundException($"Customer {customerId} not found.");
        customer.Reject(officerId);
        await _db.SaveChangesAsync(ct);
        await _bus.PublishAsync(new CustomerRejected(customer.Id, officerId, _clock.UtcNow), ct);
        return customer;
    }
