  AFTER:
    public async Task<Loan> RejectAsync(Guid loanId, string reason, CancellationToken ct = default)
    {
        if (!_user.IsInRole(Roles.LoanOfficer))
            throw new UnauthorizedAccessException("Only a loan officer may reject a loan.");

        var officerId = _user.UserId;
        if (string.IsNullOrWhiteSpace(reason))
            throw new ArgumentException("Rejection reason is required.", nameof(reason));

        var loan = await _db.Loans.FirstOrDefaultAsync(l => l.Id == loanId, ct)
                   ?? throw new KeyNotFoundException($"Loan {loanId} not found.");

        if (string.Equals(loan.CustomerId, officerId, StringComparison.Ordinal))
            throw new UnauthorizedAccessException("A loan officer cannot reject their own loan.");

        loan.Reject(officerId, reason);

        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException ex)
        {
            throw new InvalidOperationException($"Loan {loanId} is no longer submitted.", ex);
        }

        await _bus.PublishAsync(new LoanRejected(loan.Id, loan.CustomerId, _clock.UtcNow), ct);

        return loan;
    }
- [M:Bank.Modules.Loans.Application.LoanService.ComputeMonthlyPayment(System.Decimal,System.Int32)] method (new)
  AFTER:
    private static decimal ComputeMonthlyPayment(decimal principal, int termMonths)
    {
        var monthlyRate = 0.055m / 12m;
        var baseFactor = 1m + monthlyRate;
        var compoundFactor = 1m;
        for (var i = 0; i < termMonths; i++)
            compoundFactor *= baseFactor;

        var discountFactor = 1m / compoundFactor;
        var payment = principal * monthlyRate / (1m - discountFactor);
        return Math.Round(payment, 2, MidpointRounding.AwayFromZero);
    }

