        return new AccountDto(a.Id, a.Iban, a.Currency, a.Balance);
    }

    [HttpPost]
    public async Task<ActionResult<AccountDto>> Open(OpenAccountRequest request, CancellationToken ct)
    {
        var a = await _accounts.OpenAsync(request.Currency, ct);
        return new AccountDto(a.Id, a.Iban, a.Currency, a.Balance);
    }
