        new(
            p.Id,
            p.IdempotencyKey,
            p.CustomerId,
            p.FromAccountId,
            p.ToAccountId,
            p.Amount,
            p.Currency,
            p.Status,
            p.TransferId,
            p.Reference,
            p.CreatedAt)
        {
            Fee = p.Fee
        };
