        if (roundedAmount > card.PerTransactionLimit)
        {
            const string reason = "over limit";
            await _bus.PublishAsync(new CardPaymentDeclined(card.Id, reason, _clock.UtcNow), ct);
            return new CardAuthorisation(false, reason, null);
