                    throw new InvalidOperationException($"Term deposit {depositId} is not open.");

                now = clock.UtcNow;
                if (now < deposit.MaturesAt)
                    throw new InvalidOperationException($"Term deposit {depositId} has not matured yet.");

                var interest = Math.Round(
