# Loans — constitution
**Purpose:** Loan applications, credit decisions and payouts.
**Owner:** Credit · **Risk:** HIGH
**Rules:** Only loan officers decide on loans; an officer never decides on their own loan (four-eyes rule). Payouts go from LoanFunding through the Ledger.
**Forbidden:** Self-approval; paying out before approval; changing a decided loan.


===== src/Bank.Api/Modules/Loans/Domain/Loan.cs =====
using Bank.Shared.Events;

namespace Bank.Modules.Loans.Domain;

public enum LoanStatus
{
    Submitted,
    Rejected,
    Disbursed,
}

public sealed class Loan
{
    public Loan()
    {
    }

    public Guid Id { get; set; } = Guid.NewGuid();
    public string CustomerId { get; set; } = "";
    public Guid DisbursementAccountId { get; set; }
    public decimal Principal { get; set; }
    public int TermMonths { get; set; }
    public decimal AnnualRatePercent { get; set; }
    public decimal MonthlyPayment { get; set; }
    public LoanStatus Status { get; private set; } = LoanStatus.Submitted;
    public string? DecidedBy { get; set; }
    public string? DecisionNote { get; set; }
    public DateTimeOffset AppliedAt { get; set; }

    public void Approve(string officerId, string? note)
    {
        if (Status != LoanStatus.Submitted)
            throw new InvalidOperationException($"Cannot approve loan in status {Status}.");
        Status = LoanStatus.Disbursed;
        DecidedBy = officerId;
        DecisionNote = note;
    }

    public void Reject(string officerId, string reason)
    {
        if (Status != LoanStatus.Submitted)
            throw new InvalidOperationException($"Cannot reject loan in status {Status}.");
        Status = LoanStatus.Rejected;
        DecidedBy = officerId;
        DecisionNote = reason;
    }
