    public async Task<Statement> ForMonthAsync(Guid accountId, int year, int month, CancellationToken ct = default)
    {
        if (year < 1 || year > 9999)
            throw new ArgumentOutOfRangeException(nameof(year), "Year must be between 1 and 9999.");
        if (month < 1 || month > 12)
