    private sealed class SharedCallCounter
    {
        private int _count;
        public int Count => Volatile.Read(ref _count);
        public List<decimal> Amounts { get; } = new();

        public void Record(decimal amount)
        {
            Interlocked.Increment(ref _count);
            lock (Amounts)
            {
                Amounts.Add(amount);
            }
        }
    }

    private sealed class SpyLedger : ILedger
    {
        private readonly ILedger _inner;
        private readonly SharedCallCounter? _shared;
        private int _calls;
        private int _succeededCalls;

        public SpyLedger(ILedger inner, SharedCallCounter? shared = null)
        {
            _inner = inner;
            _shared = shared;
        }

        public int PostTransferCalls => Volatile.Read(ref _calls);
        public int SucceededPostTransferCalls => Volatile.Read(ref _succeededCalls);

        public async Task<Guid> PostTransferAsync(Guid fromAccountId, Guid toAccountId, decimal amount, string reference, CancellationToken ct = default)
        {
            Interlocked.Increment(ref _calls);
            _shared?.Record(amount);
            var id = await _inner.PostTransferAsync(fromAccountId, toAccountId, amount, reference, ct);
            Interlocked.Increment(ref _succeededCalls);
            return id;
        }

        public Task<IReadOnlyList<LedgerEntry>> EntriesAsync(Guid accountId, DateTimeOffset fromInclusive, DateTimeOffset toExclusive, CancellationToken ct = default) =>
            _inner.EntriesAsync(accountId, fromInclusive, toExclusive, ct);
    }

    private sealed class AsyncBarrier
    {
        private readonly int _participants;
        private readonly TaskCompletionSource _released = new(TaskCreationOptions.RunContinuationsAsynchronously);
        private int _arrived;

        public AsyncBarrier(int participants) => _participants = participants;

        public Task SignalAndWaitAsync(CancellationToken ct)
        {
            if (Interlocked.Increment(ref _arrived) >= _participants)
            {
                _released.TrySetResult();
            }
            return _released.Task.WaitAsync(ct);
        }
    }

    private sealed class BarrierAccountService : IAccountService
    {
        private readonly IAccountService _inner;
        private readonly AsyncBarrier _barrier;

        public BarrierAccountService(IAccountService inner, AsyncBarrier barrier)
        {
            _inner = inner;
            _barrier = barrier;
        }

        public Task<Account?> GetAsync(Guid id, CancellationToken ct = default) =>
            _inner.GetAsync(id, ct);

        public async Task<bool> IsOwnerAsync(Guid accountId, string userId, CancellationToken ct = default)
        {
            var result = await _inner.IsOwnerAsync(accountId, userId, ct);
            await _barrier.SignalAndWaitAsync(ct);
            return result;
        }

        public Task<IReadOnlyList<Account>> ForOwnerAsync(string ownerId, CancellationToken ct = default) =>
            _inner.ForOwnerAsync(ownerId, ct);

        public Task<Account> OpenAsync(string? currency, CancellationToken ct = default) =>
            _inner.OpenAsync(currency, ct);
    }
