    public string Currency { get; set; } = "EUR";
    /// <summary>The account balance right after this entry.</summary>
    public decimal BalanceAfter { get; set; }
    public string Reference { get; set; } = "";
    public DateTimeOffset CreatedAt { get; set; }
}


